PRINT N'Creating Trigger [dbo].[Seamap_contours_5m_mga_Drawing_upd]...';


GO
CREATE TRIGGER "Seamap_contours_5m_mga_Drawing_upd" ON [dbo].[SeamapTAS_contours_5m] AFTER UPDATE AS BEGIN SET NOCOUNT ON UPDATE "dbo"."Seamap_contours_5m_mga_Drawing" SET "Version" = COALESCE("Version", 0) + 1 WHERE "OID" IN (SELECT i."OID" FROM deleted d, inserted i WHERE d."OID" = i."OID" AND d."Geometry".STEquals(i."Geometry")=0) END;
GO
PRINT N'Creating Trigger [dbo].[Seamap_contours_5m_mga_Drawing_ins]...';


GO
CREATE TRIGGER "Seamap_contours_5m_mga_Drawing_ins" ON [dbo].[SeamapTAS_contours_5m] AFTER INSERT AS BEGIN SET NOCOUNT ON UPDATE "dbo"."Seamap_contours_5m_mga_Drawing" SET "Version" = 0 WHERE "OID" IN (SELECT "OID" FROM inserted) END;
GO
PRINT N'Creating View [dbo].[aaa_checksquidleupdates]...';


GO
CREATE VIEW aaa_checksquidleupdates as (
select a.netname, a.resname, a.zonename, a.last_modified as last_refreshed, b.last_modified as historical_refresh_date, a.annotations_data AS new_annotations_data from [squidle_annotations_data] a
left join squidle_annotations_data b
on a.netname+(case when a.resname is null then 'nores' else a.resname end)+(case when a.zonename is null then 'nd' else a.zonename end)+cast(a.highlights as varchar) =
b.netname+(case when b.resname is null then 'nores' else b.resname end)+(case when b.zonename is null then 'nd' else b.zonename end)+cast(b.highlights as varchar)
where a.annotations_data <> b.annotations_data)
GO
PRINT N'Creating View [dbo].[ACEAS_seagrass_ALL]...';


GO

CREATE VIEW ACEAS_seagrass_ALL AS
SELECT OBJECTID, Unique_ID, U_ID, S_Sea, Source, Project, geom FROM [dbo].[ACEAS_seagrass_NSW] 
UNION ALL
SELECT OBJECTID, Unique_ID, U_ID, S_Sea, Source, Project, geom FROM [dbo].[ACEAS_seagrass_NT] 
UNION ALL
SELECT OBJECTID, Unique_ID, U_ID, S_Sea, Source, Project, geom FROM [dbo].[ACEAS_seagrass_QLD] 
UNION ALL
SELECT OBJECTID, Unique_ID, U_ID, S_Sea, Source, Project, geom FROM [dbo].[ACEAS_seagrass_SA] 
UNION ALL
SELECT OBJECTID, Unique_ID, U_ID, S_Sea, Source, Project, geom FROM [dbo].[ACEAS_seagrass_TAS] 
UNION ALL
SELECT OBJECTID, Unique_ID, U_ID, S_Sea, Source, Project, geom FROM [dbo].[ACEAS_seagrass_VIC] 
UNION ALL
SELECT OBJECTID, Unique_ID, U_ID, S_Sea, Source, Project, geom FROM [dbo].[ACEAS_seagrass_WA]
GO
