CREATE view [dbo].[Aus_bathymetry_survey_extents_PUBLISHED] as
select top 100000 ID, TITLE_ASB, NAME, NETNAME AS AMP_NETWORK, RESNAME AS AMP_RESERVE, RESOLUTION AS RES_RANGE, RES_ACTUAL, METADATA AS METADATA_URL, START_DATE, END_DATE, SURVEYID, DATA_DL,

(SELECT POINTOFCONTACT = CASE
			WHEN (PRINCIPAL_INVESTIGATOR IS NULL or PRINCIPAL_INVESTIGATOR = '')
			THEN NULL
			WHEN PRINCIPAL_INVESTIGATOR LIKE '%dr %' OR PRINCIPAL_INVESTIGATOR LIKE '%dr. %' OR PRINCIPAL_INVESTIGATOR LIKE '%mr. %' OR PRINCIPAL_INVESTIGATOR LIKE '%mr %' OR PRINCIPAL_INVESTIGATOR LIKE '%ms. %' OR PRINCIPAL_INVESTIGATOR LIKE '%A/Prof. %' OR PRINCIPAL_INVESTIGATOR LIKE '%A/Prof %' OR PRINCIPAL_INVESTIGATOR LIKE '%Prof. %' OR PRINCIPAL_INVESTIGATOR LIKE '%Prof. %'
			THEN replace(replace(replace(replace(replace(replace(replace(replace(PRINCIPAL_INVESTIGATOR, 'dr ', ''), 'dr. ', ''), 'mr. ', ''), 'mr ', ''), 'ms. ', ''), 'A/Prof. ', ''), 'A/Prof ', ''), 'Prof. ', '')
			ELSE PRINCIPAL_INVESTIGATOR
			END) AS POINTOFCONTACT,

COLLECTING_ORG, VIEW_MAP, DTYPE, 
YEAR (END_DATE) AS END_YEAR,
(SELECT DTYPE_SORT = CASE
			WHEN DTYPE = 'survey'
			THEN '1'
			WHEN DTYPE = 'compilation'
			THEN '1'
			WHEN DTYPE = 'DEM'
			THEN '2'
			END) AS DTYPE_SORT,

(SELECT AVAIL_SORT = CASE
			WHEN DATA_DL like 'yes%'
			THEN '1'
			ELSE '2'
			END) AS AVAIL_SORT,
GEOM
FROM [dbo].[Aus_bathymetry_ALL_SURVEYS]
WHERE NAME NOT LIKE '% - PLANNED'
AND TYPEID <> 'S.9999'
AND 1 <> CASE WHEN ((collecting_org = 'WA Department of Transport' and bathy_url = 'https://maps.slip.wa.gov.au/Marine/app/') or surveyid = 'AU20171102_Multi') THEN 1 ELSE 0 END
ORDER BY data_dl desc, res_actual asc
GO
