CREATE VIEW [dbo].[SeamapAus_BOUNDARIES_TasAbFishBlocks_MAP_codepreserve] AS
SELECT * FROM

(
SELECT A.*, B.geom_block FROM 
(select * from [dbo].[SeamapAus_BOUNDARIES_TasAbFishBlocks]
) A

LEFT JOIN

---AGGREGATE GEOMETRY BY NETWORK
(select T.style_id, T.geom_block, T.blockno
 FROM (
select blockno, min(ID) as style_id, geometry::UnionAggregate(geom.STBuffer(1)).MakeValid() AS geom_block from [dbo].[SeamapAus_BOUNDARIES_TasAbFishBlocks] group by blockno
 ) AS T) B

 ON A.ID = B.style_id
 ) Z
GO
