CREATE view [dbo].[SeamapAus_Boundaries_View]
as
select 'seamap:SeamapAus_BOUNDARIES_AMP2018_NETWORKS' as boundary_layer, NETNAME as region, geom from dbo.SeamapAus_BOUNDARIES_AMP2018_NETWORKS
union all
--select 'seamap:SeamapAus_BOUNDARIES_AMP2018_RESERVES_OLD' as boundary_layer, RESNAME as region, geom_RESERVE as geom from dbo.SeamapAus_AMP2018_MAP WHERE geom_RESERVE IS NOT NULL
--union all
select 'seamap:SeamapAus_BOUNDARIES_AMP2018_RESERVES' as boundary_layer, RESNAME as region, geom from dbo.SeamapAus_BOUNDARIES_AMP2018_RESERVES
union all
--select 'seamap:SeamapAus_BOUNDARIES_AMP2018_ZONES_OLD' as boundary_layer, RES_ZONE as region, geom_ZONE as geom from dbo.SeamapAus_AMP2018_MAP WHERE geom_ZONE IS NOT NULL
--union all
select 'seamap:SeamapAus_BOUNDARIES_AMP2018_ZONES' as boundary_layer, POLYGONID as region, geom from dbo.SeamapAus_BOUNDARIES_AMP2018_ZONES_UNIQUE
union all
select 'seamap:SeamapAus_BOUNDARIES_AMP2018_ZONE_X_NET' as boundary_layer, NETNAME+' Network - '+ZONENAME as region, geom from dbo.SeamapAus_BOUNDARIES_AMP2018_ZONE_X_NET
union all
select 'seamap:SeamapAus_BOUNDARIES_AMP2018_ZONE_X_RES' as boundary_layer, RESNAME+' - '+ZONENAME as region, geom from dbo.SeamapAus_BOUNDARIES_AMP2018_ZONE_X_RES
union all
select 'seamap:SeamapAus_BOUNDARIES_MEOW3112_PROV' as boundary_layer, region, geom from dbo.SeamapAus_BOUNDARIES_MEOW3112_PROV
union all
select 'seamap:SeamapAus_BOUNDARIES_IMCRA_PROVBIO' as boundary_layer, region, geom from dbo.SeamapAus_BOUNDARIES_IMCRA_PROVBIO;
