PRINT N'Creating View [dbo].[SeamapAus_NBHL_level_classification_codepreserve]...';


GO




CREATE view [dbo].[SeamapAus_NBHL_level_classification_codepreserve] AS
(
SELECT geom, x.BC_level as BC_level, x.SC_level AS SC_level,
CASE WHEN BC_level IS NOT NULL AND BC_level <> 'Unknown' THEN x.BC_LEVEL
     WHEN BC_level IS NULL THEN x.SC_LEVEL
     WHEN BC_level = 'Unknown' AND SC_level <> 'Unknown' THEN x.SC_LEVEL
	 ELSE 'Unknown'
     END AS [LEVEL]
FROM FINALPRODUCT_SeamapAus_current a
INNER JOIN
	(SELECT ID,
		CASE WHEN bc_level4<>'NA' AND bc_level4<>'unknown' THEN 'BC4'
			 WHEN (bc_level4='NA' OR bc_level4='unknown') AND (bc_level3<>'NA' AND bc_level3<>'unknown') THEN 'BC3'
			 WHEN (bc_level4='NA' OR bc_level4='unknown') AND (bc_level3='NA' OR bc_level3='unknown') AND (bc_level2<>'NA' AND bc_level2<>'unknown') THEN 'BC2'
			 WHEN (bc_level4='NA' OR bc_level4='unknown') AND (bc_level3='NA' OR bc_level3='unknown') AND (bc_level2='NA' OR bc_level2='unknown') AND (bc_level1<>'NA' AND bc_level1<>'unknown') THEN 'BC1'
			 WHEN bc_level1 = 'Unknown' THEN 'Unknown'
		END AS BC_level,
		CASE WHEN sc_level4<>'NA' AND sc_level4<>'unknown' THEN 'SC4'
			 WHEN (sc_level4='NA' OR sc_level4='unknown') AND (sc_level3<>'NA' AND sc_level3<>'unknown') THEN 'SC3'
			 WHEN (sc_level4='NA' OR sc_level4='unknown') AND (sc_level3='NA' OR sc_level3='unknown') AND (sc_level2<>'NA' AND sc_level2<>'unknown') THEN 'SC2'
			 WHEN (sc_level4='NA' OR sc_level4='unknown') AND (sc_level3='NA' OR sc_level3='unknown') AND (sc_level2='NA' OR sc_level2='unknown') AND (sc_level1<>'NA' AND sc_level1<>'unknown') THEN 'SC1'
			 WHEN sc_level1 = 'Unknown' THEN 'Unknown'
		END AS SC_level
		FROM FINALPRODUCT_SeamapAus_current) AS x
ON a.ID = x.ID
)
GO
