GO





CREATE VIEW [dbo].[TRANSFORM_GLOBALARCHIVE_DEPLOYMENT_POINTS_APPENDED] AS
(
SELECT FID AS ID,
(CASE WHEN data_open IS NULL THEN 'N' ELSE data_open END) AS data_open,
project_name, project_url, campaign_id,
(CASE	WHEN CAMPAIGN_NAME LIKE '%metadata%' THEN left(campaign_name, (charindex('_metadata', campaign_name) -1))
		WHEN CAMPAIGN_NAME = 'NA' AND campaign_link like '%831%' THEN '2017-02_Neptunes.BRUVS_monoBRUVS'
		WHEN CAMPAIGN_NAME = 'NA' AND campaign_link like '%832%' THEN '2017-02_Neptunes.BRUVS_pelagicBRUVS'
		ELSE campaign_name END) AS campaign_name,
campaign_url, 
(CASE	WHEN ((campaign_name like '%stereo%' or campaign_name like '%stero%') AND method_name = 'Please see link for details') THEN 'stereo-BRUVs'
		WHEN campaign_name like '%BOSS%' AND method_name = 'Please see link for details' THEN 'stereo-BOSS'
		WHEN campaign_name like '%monopegalic%' AND method_name = 'Please see link for details' THEN 'monopelagic-BRUVs'
		WHEN campaign_name like '%BRUV%' AND method_name = 'Please see link for details' THEN 'BRUVs'
		WHEN (campaign_name = '13-11_Outer Islands' OR campaign_name = 'CBMP2015' OR campaign_name = 'NA')
			AND method_name = 'Please see link for details'  THEN 'mono-BRUVs'
		WHEN (campaign_name = '16-04_AB' OR campaign_name = '14-10_Ellen' OR campaign_name = '13-02_TNP' OR campaign_name = '14-05_WaltersShoal' OR campaign_name = '16-03_Amathole'
			OR campaign_name = '15-03_DH' OR campaign_name = '15-06_FalseBay' OR campaign_name = '15-06_AB' OR campaign_name = '17-06_ISI' OR campaign_name = '14-05_WaltersShoal'
			OR campaign_name = 'EMR_Complete_20201029' OR campaign_name = '17-04_NSC' OR campaign_name = '15-05_Pondo' OR campaign_name = '2008-2011_DEW_SA_NRMbiodiversityProjects'
			OR campaign_name = '201811_SA_MPA_PearsonExpedition' OR campaign_name = '201905-201909_SA_DEW_SAWater_Sleaford Monitoring' OR campaign_name = 'Arafura CMR')
			AND method_name = 'Please see link for details'  THEN 'stereo-BRUVs'
		WHEN project_name = 'FRDC low catch zone'
			AND method_name = 'Please see link for details'  THEN 'Trapping'
		WHEN campaign_name = '2011-05_Rottnest.sanctuaries_UVC'
			AND method_name = 'Please see link for details'  THEN 'UVC'
		WHEN campaign_name = '2016-01_Mackerel.Islands.Shallow_SPC'
			AND method_name = 'Please see link for details'  THEN 'SPC'
		WHEN project_name = 'Great Barrier Island Marine Reserve'
			AND method_name = 'Please see link for details'  THEN 'BUV'
		ELSE method_name END) AS method_name,
deployment_id,
cast(deployment_time as date) AS deployment_date,
cast(deployment_time as time(0)) AS deployment_time,
description, deployment_mins, location, status, depth, geom
FROM 
(
SELECT *
FROM TRANSFORM_GLOBALARCHIVE_DEPLOYMENT_POINTS a
LEFT JOIN
(SELECT DATA_OPEN, PROJECT_URL, CAMPAIGN_NAME AS campaign_name_b, CAMPAIGN_URL, DEPLOYMENT_MINS
FROM EXTRACT_GLOBALARCHIVE_DEPLOYMENT_POINTS_appendix  ---remove duplicated Cocos Islands
where campaign_url <> 'https://globalarchive.org/geodata/data/campaign/get/797') b
ON a.campaign_name = b.campaign_name_b
) x
WHERE campaign_link <> 'https://globalarchive.org/geodata/data/campaign/get/797'  ---remove duplicated Cocos Islands (has to happen twice)
AND campaign_name not like '%test%' AND campaign_name not like '%greyb%' AND project_name not like '%test%' AND project_name not like '%greyb%' ---remove "test" campaigns/projects
)
GO
PRINT N'Creating View [dbo].[VW_AMP_DEPTHZONES]...';


GO
CREATE VIEW [dbo].[VW_AMP_DEPTHZONES] AS
(
    SELECT NETNAME, RESNAME,
        CASE
            WHEN ZONENAME = 'shallow' THEN 'Shallow'
            WHEN ZONENAME = 'mesophotic' THEN 'Mesophotic'
            WHEN ZONENAME = 'rariphotic' THEN 'Rariphotic'
            WHEN ZONENAME = 'upper slope' THEN 'Upper slope'
            WHEN ZONENAME = 'mid slope' THEN 'Mid slope'
            WHEN ZONENAME = 'lower slope' THEN 'Lower slope'
            WHEN ZONENAME = 'abyss' THEN 'Abyss'
            WHEN ZONENAME = 'hadal' THEN 'Hadal'
        END AS ZONENAME,
        CASE
            WHEN ZONENAME = 'shallow' THEN 0
            WHEN ZONENAME = 'mesophotic' THEN 30
            WHEN ZONENAME = 'rariphotic' THEN 70
            WHEN ZONENAME = 'upper slope' THEN 200
            WHEN ZONENAME = 'mid slope' THEN 700
            WHEN ZONENAME = 'lower slope' THEN 2000
            WHEN ZONENAME = 'abyss' THEN 4000
            WHEN ZONENAME = 'hadal' THEN 6000
        END AS MIN,
        CASE
            WHEN ZONENAME = 'shallow' THEN 30
            WHEN ZONENAME = 'mesophotic' THEN 70
            WHEN ZONENAME = 'rariphotic' THEN 200
            WHEN ZONENAME = 'upper slope' THEN 700
            WHEN ZONENAME = 'mid slope' THEN 2000
            WHEN ZONENAME = 'lower slope' THEN 4000
            WHEN ZONENAME = 'abyss' THEN 6000
            WHEN ZONENAME = 'hadal' THEN 20000
        END AS MAX
    FROM AMP_SUMMARY_MERI_depth
    
    UNION ALL
    
	---manually add 'shallow' zone for Cod Grounds (250m grid indicates no shallow areas, but some SQ+ surveys are <30m depth)
    SELECT 
        'Temperate East' AS NETNAME,
        'Cod Grounds' AS RESNAME,
        'Shallow' AS ZONENAME,
        0 AS MIN,
        30 AS MAX
)
GO
