CREATE VIEW [dbo].[VW_AMP_SUMMARY_network_by_MERIdepth] AS
(select a.NETNAME AS NETWORK, a.ZONENAME AS ZONE_NAME, a.DEPTH AS DEPTH_RANGE, ROUND(a.geom.STArea()/1000000,2) as AREA_km2, ROUND((a.geom.STArea()/x.AREA_res)*100,2) AS AREA_percent
FROM 
	(SELECT NETNAME, ZONENAME, DEPTH, geometry::UnionAggregate(geom) AS geom
	FROM AMP_SUMMARY_MERI_DEPTH
	GROUP BY NETNAME, ZONENAME, DEPTH) a
INNER JOIN 
(select	NETNAME,
			geometry::UnionAggregate(geom).STArea() as AREA_res
			from AMP_SUMMARY_MERI_DEPTH
			group by NETNAME) x
ON a.NETNAME = x.NETNAME)
GO
