PRINT N'Creating View [dbo].[VW_BATHYMETRY]...';


GO





CREATE view [dbo].[VW_BATHYMETRY] as
select ID,
(SELECT RES_ACTUAL = CASE
			WHEN RES_ACTUAL <=2 THEN '2m or less'
			WHEN RES_ACTUAL >2 AND RES_ACTUAL <=10 THEN '3-10m'
			WHEN RES_ACTUAL >10 AND RES_ACTUAL <=20 THEN '11-20m'
			/*** Special case handling for pending AHO surveys (30m) that are not yet published ***/
			WHEN RES_ACTUAL >20 AND RES_ACTUAL <=50 AND data_dl <> 'no' THEN '21-50m'
			WHEN RES_ACTUAL >50 AND RES_ACTUAL <=100 THEN '51-100m'
			WHEN RES_ACTUAL >100 THEN '> 100m'
			ELSE 'Unknown'
			END) AS RESOLUTION,
(SELECT RES_ACTUAL = CASE
			WHEN RES_ACTUAL <=2 THEN 1
			WHEN RES_ACTUAL >2 AND RES_ACTUAL <=10 THEN 2
			WHEN RES_ACTUAL >10 AND RES_ACTUAL <=20 THEN 3
			/*** Special case handling for pending AHO surveys (30m) that are not yet published ***/
			WHEN RES_ACTUAL >20 AND RES_ACTUAL <=50 AND data_dl <> 'no' THEN 4
			WHEN RES_ACTUAL >50 AND RES_ACTUAL <=100 THEN 5
			WHEN RES_ACTUAL >100 THEN 6
			ELSE 7
			END) AS [RANK]
,geom
FROM [dbo].[Aus_bathymetry_ALL_SURVEYS]
WHERE DTYPE <> 'DEM' AND name NOT LIKE '% - PLANNED'
AND TYPEID <> 'S.9999'
AND 1 <> CASE WHEN (COLLECTING_ORG = 'WA Department of Transport' and bathy_url = 'https://maps.slip.wa.gov.au/Marine/app/') THEN 1 ELSE 0 END
GO
