CREATE VIEW [dbo].[VW_HABITAT_OBS_GLOBALARCHIVE] AS
(SELECT
CAMPAIGN_NAME,
ID AS DEPLOYMENT_ID,
CASE
	WHEN year(deployment_date)<1980 AND campaign_name = '2007-11_Point.Ann.MF_stereoBRUVs' THEN '2017-11-14'
	WHEN year(deployment_date)<1980 AND campaign_name = '2010-03_Rottnest.sanctuaries_stereoDOVs' THEN '2010-03-01'
	WHEN year(deployment_date)<1980 AND campaign_name = '2011-05_Rottnest.sanctuaries_UVC' THEN '2011-05-01'
	WHEN campaign_name = '20181_SA_Com_PearsonExpedition_PelagicBRUVS' THEN cast('2018'+right(deployment_date, 6) as date)
	ELSE deployment_date
	END
	AS DATE,
method_name AS METHOD,
DEPTH,
deployment_mins AS video_time,
data_open,
geom
FROM TRANSFORM_GLOBALARCHIVE_DEPLOYMENT_POINTS_APPENDED
---the below is error filtering to remove sketchy data (no dates and 0 values for depth...)
WHERE
NOT (campaign_name = '2007-05_Jurien.Bay.MF_stereoBRUVs' AND year(deployment_date)<1980)
AND NOT (campaign_name = '2008-02_Broke.Inlet.MF_stereoBRUVs' AND year(deployment_date)<1980)
AND NOT (campaign_name = '2007-11_Two.Peoples.MF_stereoBRUVs' AND year(deployment_date)<1980)
AND NOT (campaign_name = '2007-05_Abrolhos.MF_stereoBRUVs' AND year(deployment_date)<1980)
AND NOT (campaign_name = '2008-08_Dampier.Pluto_stereoBRUVs' AND year(deployment_date)<1980)
AND NOT (campaign_name = '2011-05_Rottnest.sanctuaries_stereoDOVs' AND year(deployment_date)<1980)

)
GO
