GO

CREATE VIEW [dbo].[VW_HABITAT_OBS_SEDIMENT] AS
(SELECT survey_name AS SURVEY, fid AS SAMPLE_ID,
(CASE WHEN acquire_date = '' OR acquire_date = '1900-01-01' THEN NULL
WHEN year(acquire_date) = '0020' THEN dateadd(year, 2000, CAST(acquire_date AS DATE))
WHEN survey_name = 'East Australia Phosphates' AND year(acquire_date) = '1900' THEN dateadd(year, 87, CAST(acquire_date AS DATE))
WHEN survey_name = 'Great Barrier Reef Seabed Biodiversity Project Lady Basten Cruise' AND year(acquire_date) = '1900' THEN dateadd(year, 103, CAST(acquire_date AS DATE))
WHEN survey_name = 'Eltanin Cruise 35' AND year(acquire_date) < 1950 THEN dateadd(year, 63, CAST(acquire_date AS DATE))
WHEN survey_name = 'Eltanin Cruise 45' AND year(acquire_date) < 1950 THEN dateadd(year, 65, CAST(acquire_date AS DATE))
ELSE CAST (acquire_date AS DATE) END)
AS DATE,
sample_type AS METHOD,
(CASE WHEN MUD_PERCENT IS NULL AND SAND_PERCENT IS NULL AND GRAVEL_PERCENT IS NULL AND CARBONATE_PERCENT IS NULL AND BIOGENIC_SILICA_PERCENT IS NULL AND MEAN_GRAIN_SIZE IS NULL AND FOLK_CLASS = '' THEN 'NO' ELSE 'YES' END) AS ANALYSED,
geom
from
[TRANSFORM_MARS])
