CREATE VIEW [dbo].[VW_IMAGERY_SQUIDLE_AMP_NETWORK] AS (
  SELECT
    [Network],
    'https://squidle.org/api/media?q={"filters":[{"name":"deployment_id","op":"in","val":['
	+
		STUFF((
		SELECT CONCAT(',',t1.observation) ---specify comma separator
		FROM BOUNDARY_AMP_HABITAT_OBS_SQUIDLE t1
		WHERE t1.network = t.network
		FOR XML PATH ('') ---specifies no <xml> separators - ie put everything on one line
		), 1, 1, '') ---go to first value, remove 1 character, replace with '' (removes leading comma)
	+    
	']}],"order_by":[{"random":true}],"limit":10}' AS [NRandImage_URL]
  FROM BOUNDARY_AMP_HABITAT_OBS_SQUIDLE t
  GROUP BY [Network]
)
