PRINT N'Creating View [dbo].[VW_TIMELINE_BATHYMETRY_SURVEYS]...';


GO




CREATE VIEW [dbo].[VW_TIMELINE_BATHYMETRY_SURVEYS] AS

(SELECT DISTINCT P2.NETWORK, P2.PARK, P1.NAME AS SURVEY_NAME, YEAR(P1.end_date) AS YEAR
	FROM (

---to select only the duplicated instances, aggregate geometry and compact down to a single survey
		SELECT dups.title_asb, dups.title_asb AS NAME, x.end_date, geometry::UnionAggregate(x.geom) AS geom
		FROM Aus_bathymetry_ALL_SURVEYS x
		INNER JOIN 
			(SELECT title_asb, countunique
			FROM
				(select title_asb, count(*) as countunique
				from Aus_bathymetry_ALL_SURVEYS
				group by title_asb) x
			WHERE (x.countunique >1 and x.title_ASB IS NOT NULL) ---only select duplicated layers (multiple rows with same title_ASB) - but ignoring NULL values of title_ASB (many of these)
			) dups 		
		ON dups.title_asb = x.title_asb
		GROUP BY dups.title_asb, x.end_date

		UNION ALL

----to select the all content from the parent table LESS the duplicated records
		SELECT title_asb, name, end_date, geom
		FROM Aus_bathymetry_ALL_SURVEYS 
		WHERE end_date IS NOT NULL
		AND NOT (data_dl = 'yes - other' AND METADATA IS NULL) ---remove manually-added extents from IMAS, NESP etc holdings
		AND NOT (dtype = 'DEM' or dtype = 'compilation') ---remove compilations (should be in individual surveys) and DEMs
		AND ID NOT IN --- exclude the duplicate surveys already compacted down (previous section)
			(
			SELECT sub.ID
			FROM Aus_bathymetry_ALL_SURVEYS sub
			INNER JOIN (
				SELECT title_asb, countunique
				FROM (
					select title_asb, count(*) as countunique
					from Aus_bathymetry_ALL_SURVEYS
					group by title_asb) a
					where (a.countunique >1 and title_ASB IS NOT NULL)
					) b
			ON sub.title_asb = b.title_asb
			)
	) P1

INNER JOIN VW_BOUNDARY_AMP P2
ON P1.geom.STIntersects(P2.geom) = 1
WHERE end_date < GETDATE() AND YEAR(P1.end_date) > 1950 AND P1.end_date IS NOT NULL ---filter out dodgy surveys with incorrect dates or surveys still underway
)
GO
