PRINT N'Creating View [dbo].[AMP_bathy_mapping_stats_NETWORK]...';


GO


CREATE VIEW [dbo].[AMP_bathy_mapping_stats_NETWORK] AS
(
select a.Network,
CASE WHEN b.bathymetry_resolution IS NULL THEN '-' WHEN b.bathymetry_resolution = 'unknown' THEN 'not public (unknown)' ELSE b.bathymetry_resolution END AS bathymetry_resolution,
CASE WHEN b.area_mapped IS NULL THEN 0 ELSE round(b.area_mapped/1000000,1) END AS mapped_km2,
CASE WHEN b.area_mapped is null THEN '-' ELSE cast(round((b.area_mapped/c.total_area_mapped)*100,1) as nvarchar) END AS percent_of_mapped,
CASE WHEN b.area_mapped IS NULL THEN '-' ELSE cast(round((b.area_mapped/a.area_network)*100,1) as nvarchar) END AS percent_of_total
FROM (

	(SELECT Network, geometry::UnionAggregate(geom).STArea() as area_network
		FROM VW_BOUNDARY_AMP
		WHERE NETWORK <> 'HIMI'
		group by Network) a
		LEFT JOIN
	(SELECT Network, bathymetry_resolution, geometry::UnionAggregate(geom).STArea() as area_mapped
		FROM BOUNDARY_AMP_BATHYMETRY
		group by Network, bathymetry_resolution) b
		ON a.Network = b.Network
		LEFT JOIN
	(SELECT Network, geometry::UnionAggregate(geom).STArea() as total_area_mapped
		FROM BOUNDARY_AMP_BATHYMETRY
		GROUP BY Network) c
		ON b.Network = c.Network
	)
---add a 'total mapped' figure for Network
UNION ALL
	(SELECT a.Network, 'total mapped' AS bathymetry_resolution, round(a.area_mapped/1000000,1) AS area_mapped, cast(a.percent_of_mapped as nvarchar), cast(round((a.area_mapped/b.area_network)*100,1) as nvarchar) AS percent_of_total
	FROM
		(SELECT Network, geometry::UnionAggregate(geom).STArea() as area_mapped, '-' AS percent_of_mapped
		FROM BOUNDARY_AMP_BATHYMETRY 
		GROUP BY network) a
	LEFT JOIN
		(SELECT Network, geometry::UnionAggregate(geom).STArea() as area_network
		FROM VW_BOUNDARY_AMP
		group by Network) b
		ON a.Network = b.Network
	)

)
GO
PRINT N'Creating View [dbo].[AMP_bathy_mapping_stats_PARK]...';


GO



CREATE VIEW [dbo].[AMP_bathy_mapping_stats_PARK] AS
(
select a.park,
CASE WHEN b.bathymetry_resolution IS NULL THEN '-' WHEN b.bathymetry_resolution = 'unknown' THEN 'not public (unknown)' ELSE b.bathymetry_resolution END AS bathymetry_resolution,
CASE WHEN b.area_mapped IS NULL THEN 0 ELSE round(b.area_mapped/1000000,1) END AS mapped_km2,
CASE WHEN b.area_mapped is null THEN '-' ELSE cast(round((b.area_mapped/c.total_area_mapped)*100,1) as nvarchar) END AS percent_of_mapped,
CASE WHEN b.area_mapped IS NULL THEN '-' ELSE cast(round((b.area_mapped/a.area_park)*100,1) as nvarchar) END AS percent_of_total
FROM (

	(SELECT park, geometry::UnionAggregate(geom).STArea() as area_park
		FROM VW_BOUNDARY_AMP
		WHERE park <> 'HIMI'
		group by park) a
		LEFT JOIN
	(SELECT park, bathymetry_resolution, geometry::UnionAggregate(geom).STArea() as area_mapped
		FROM BOUNDARY_AMP_BATHYMETRY
		group by park, bathymetry_resolution) b
		ON a.park = b.park
		LEFT JOIN
	(SELECT park, geometry::UnionAggregate(geom).STArea() as total_area_mapped
		FROM BOUNDARY_AMP_BATHYMETRY
		GROUP BY park) c
		ON b.park = c.park
	)
---add a 'total mapped' figure for park
UNION ALL
	(SELECT a.park, 'total mapped' AS bathymetry_resolution, round(a.area_mapped/1000000,1) AS area_mapped, cast(a.percent_of_mapped as nvarchar), cast(round((a.area_mapped/b.area_park)*100,1) as nvarchar) AS percent_of_total
	FROM
		(SELECT park, geometry::UnionAggregate(geom).STArea() as area_mapped, '-' AS percent_of_mapped
		FROM BOUNDARY_AMP_BATHYMETRY 
		GROUP BY park) a
	LEFT JOIN
		(SELECT park, geometry::UnionAggregate(geom).STArea() as area_park
		FROM VW_BOUNDARY_AMP
		group by park) b
		ON a.park = b.park
	)

)
GO
PRINT N'Creating View [dbo].[AMP_state_of_knowledge_NETWORK]...';


GO





CREATE VIEW [dbo].[AMP_state_of_knowledge_NETWORK] AS

(

SELECT
	agg.NETWORK,
	agg.bathy_score,
	agg.hab_score,
	CASE WHEN agg.SQUIDLE_score IS NULL THEN 0 ELSE agg.SQUIDLE_score END AS SQUIDLE_score,
	CASE WHEN agg.GA_score IS NULL THEN 0 ELSE agg.GA_score END AS GA_score,
	CASE WHEN agg.MARS_score IS NULL THEN 0 ELSE agg.MARS_score END AS MARS_score,
	agg.GA_score+agg.SQUIDLE_score+agg.MARS_score AS HabObs_combined_score
FROM (

---SELECT weighted bathy, habitat, GlobalArchive, Squidle, MARS score-per-region
	SELECT a.NETWORK,
		CASE WHEN bathy_weighted IS NULL THEN 0 ELSE sum(bathy_weighted/area_NETWORK) END as bathy_score,---weighted coverage per unit area
		CASE WHEN hab_area_mapped is NULL THEN 0 ELSE sum(hab_area_mapped/area_NETWORK) END as hab_score, ---coverage per unit area
		CASE WHEN GA_score IS NULL THEN 0 ELSE (GA_score/area_NETWORK)*1000000 END as GA_score, ---observations per square kilometer
		CASE WHEN squidle_score IS NULL THEN 0 ELSE (squidle_score/area_NETWORK)*1000000 END as squidle_score, ---observations per square kilometer
		CASE WHEN MARS_score IS NULL THEN 0 ELSE (MARS_score/area_NETWORK)*1000000 END as MARS_score ---observations per square kilometer
		FROM (

---select region area for NETWORK
			(SELECT NETWORK, geometry::UnionAggregate(geom).STArea() as area_NETWORK
			FROM VW_BOUNDARY_AMP
			WHERE NETWORK <> 'HIMI'
			group by NETWORK) a

---STEP 1: get  habitat score-per-region (unweighted % only)
			LEFT JOIN
			(SELECT NETWORK, geometry::UnionAggregate(geom).STArea() as hab_area_mapped
			FROM BOUNDARY_AMP_HABITAT
			GROUP BY NETWORK) hab
			ON a.NETWORK = hab.NETWORK

---STEP 2: select bathy area mapped per resolution bin, and apply weighting (1 = <2m, 2 = 3-10m, 3 = 11-20m, 4, = 21-50m, 5 = >50m, 6 = unknown)
			LEFT JOIN
			(SELECT NETWORK, sum(res_weighting*area_mapped) AS bathy_weighted
			FROM	(SELECT NETWORK,
					CASE WHEN bathymetry_rank >= 6 THEN 0.5
					WHEN bathymetry_rank = 5 THEN 1
					WHEN bathymetry_rank = 4 THEN 3
					WHEN bathymetry_rank = 3 THEN 5
					WHEN bathymetry_rank = 2 THEN 7
					WHEN bathymetry_rank = 1 THEN 8
					END AS res_weighting,
					geometry::UnionAggregate(geom).STArea() as area_mapped
					FROM BOUNDARY_AMP_BATHYMETRY
					group by NETWORK, bathymetry_rank
					) sub
			GROUP BY NETWORK
			) bathy	
			ON a.NETWORK = bathy.NETWORK)

---STEP 3: select GlobalArchive and apply multiplicative weightings: <3 years old = 2, 3-5 years old = 1.5, otherwse 1. Multiplied by 1.5 if public/open.
			LEFT JOIN
			(SELECT NETWORK, sum(GA_weighting) AS GA_score
			FROM
			(SELECT NETWORK, date_weighting*openness_weighting AS GA_weighting
				FROM (
				SELECT NETWORK,
				CASE	WHEN datediff(month, deployment_date, getdate()) <= 36 THEN 2
						WHEN datediff(month, deployment_date, getdate()) BETWEEN 37 AND 60 THEN 1.5
							ELSE 1 END
						AS date_weighting,
				CASE	WHEN data_open = 'Y' THEN 1.5
						ELSE 1 END
						AS openness_weighting
				FROM BOUNDARY_AMP_HABITAT_OBS_GLOBALARCHIVE a
			INNER JOIN ---aggregates based on geometry (reduced overlapping points to single point)
			(
				SELECT id, deployment_date, data_open
				FROM TRANSFORM_GLOBALARCHIVE_DEPLOYMENT_POINTS_APPENDED
				WHERE
				substring(id, charindex('.', id)+1, len(id)-charindex('.', id)) ---deals with non-numeric ID column
				IN (
					SELECT MIN(substring(id, charindex('.', id)+1, len(id)-charindex('.', id))) ---selects minimum ID (we don't care which overlapping point we choose)
					FROM TRANSFORM_GLOBALARCHIVE_DEPLOYMENT_POINTS_APPENDED
					GROUP BY round(geom.STY/5,0)*5 ---round to nearest 5m
					)
				) b
			ON a.OBSERVATION=b.ID) sub1
			) sub2
			GROUP BY NETWORK) ga
			ON a.NETWORK = ga.NETWORK

---STEP 4: select Squidle and apply multiplicative weightings: <3 years old = 2, 3-5 years old = 1.5, otherwise 1. Multiplied by 1.5 if annotated (but private), multiplied by 2 if annotated and public
-----------CURRENTLY multiplied by image count
			LEFT JOIN
			(SELECT NETWORK, sum(squidle_weighting) AS squidle_score
			FROM (
				SELECT NETWORK, date_weighting*annotations_weighting*images AS squidle_weighting ---multiplying by weighting and image count
				FROM (
				SELECT NETWORK, images,
					CASE	WHEN datediff(month, DATE, getdate()) <= 36 THEN 2
					WHEN datediff(month, DATE, getdate()) BETWEEN 37 AND 60 THEN 1.5
					ELSE 1 END
					AS date_weighting,
					CASE	WHEN total_annotations > 0 AND public_annotations = 0 THEN 1.5
					WHEN total_annotations > 0 AND public_annotations > 0 THEN 2
					ELSE 1 END
					AS annotations_weighting
				FROM BOUNDARY_AMP_HABITAT_OBS_SQUIDLE a
				INNER JOIN ---aggregates based on geometry (reduced overlapping points to single point)
				(
				select * FROM VW_HABITAT_OBS_SQUIDLE
				WHERE DEPLOYMENT_ID
				IN (
					SELECT MIN(DEPLOYMENT_ID)
					FROM VW_HABITAT_OBS_SQUIDLE
					GROUP BY round(geom.STY/5,0)*5 ---round to nearest 5m
					)
				) b
				ON a.OBSERVATION=b.DEPLOYMENT_ID) sub1
				) sub2
			GROUP BY NETWORK) sq
			ON a.NETWORK = sq.NETWORK


---STEP 5: select MARS sediment and apply multiplicative weightings: <3 years old = 2, 3-5 years old = 1.5, otherwise 1. Multiplied by by 2 if analysed.
			LEFT JOIN
			(SELECT NETWORK, sum(MARS_weighting) AS MARS_score
			FROM (
			SELECT NETWORK, date_weighting*analysed_weighting AS MARS_weighting
				FROM (
					SELECT NETWORK,
					CASE	WHEN datediff(month, DATE, getdate()) <= 36 THEN 2
							WHEN datediff(month, DATE, getdate()) BETWEEN 37 AND 60 THEN 1.5
							ELSE 1 END
							AS date_weighting,
					CASE	WHEN b.ANALYSED = 'YES' THEN 2
							ELSE 2 END
							AS analysed_weighting
					FROM BOUNDARY_AMP_HABITAT_OBS_SEDIMENT a
					INNER JOIN ---aggregates based on geometry (reduced overlapping points to single point)
					(
					SELECT * FROM VW_HABITAT_OBS_SEDIMENT
					WHERE SAMPLE_ID
					IN (
						SELECT MIN(SAMPLE_ID)
						FROM VW_HABITAT_OBS_SEDIMENT
						GROUP BY round(geom.STY/5,0)*5 ---round to nearest 5m
						)
					) b
					ON a.OBSERVATION=b.sample_id) sub1
				) sub2
				GROUP BY NETWORK) m
				ON a.NETWORK = m.NETWORK

	GROUP BY a.NETWORK, a.area_NETWORK, bathy.bathy_weighted, hab.hab_area_mapped, ga.GA_score, sq.squidle_score, m.MARS_score

	) agg
)
GO
