CREATE VIEW [dbo].[AMP_state_of_knowledge_NETWORK_WEIGHTED] AS (
select network,
---score bathy from 0-5 for star rating in Data Reports
round(bathy_score/(select max(bathy_score) from AMP_state_of_knowledge_network) * 5,1) AS bathy_SCORE, 
---score habitat from 0-1 (as we know habitat coverage is poor everywhere!)
round(hab_score/(select max(hab_score) from AMP_state_of_knowledge_network),1) AS hab_SCORE,
---score squidle obs from 0-5 for star rating in Data Reports
round(squidle_score/(select max(squidle_score) FROM AMP_state_of_knowledge_network) *5,1) AS squidle_SCORE,
---score GlobalArchive obs from 0-5 for star rating in Data Reports
round(GA_SCORE/(select max(GA_SCORE) FROM AMP_state_of_knowledge_network) *5,1) AS GA_SCORE,
---score Sediment samples from 0-5 for star rating in Data Reports
round(MARS_score/(select max(MARS_score) FROM AMP_state_of_knowledge_network) *5,1) AS MARS_score,
---score habitat obs combined from 0-5 for star rating in Data Reports
round(HabObs_combined_score/(select max(HabObs_combined_score) FROM AMP_state_of_knowledge_network) *5,1) AS HabObs_combined_score
FROM AMP_state_of_knowledge_network)
GO
PRINT N'Creating View [dbo].[AMP_state_of_knowledge_PARK]...';


GO





CREATE VIEW [dbo].[AMP_state_of_knowledge_PARK] AS

(

SELECT
	agg.PARK,
	agg.bathy_score,
	agg.hab_score,
	CASE WHEN agg.SQUIDLE_score IS NULL THEN 0 ELSE agg.SQUIDLE_score END AS SQUIDLE_score,
	CASE WHEN agg.GA_score IS NULL THEN 0 ELSE agg.GA_score END AS GA_score,
	CASE WHEN agg.MARS_score IS NULL THEN 0 ELSE agg.MARS_score END AS MARS_score,
	agg.GA_score+agg.SQUIDLE_score+agg.MARS_score AS HabObs_combined_score
FROM (

---SELECT weighted bathy, habitat, GlobalArchive, Squidle, MARS score-per-region
	SELECT a.PARK,
		CASE WHEN bathy_weighted IS NULL THEN 0 ELSE sum(bathy_weighted/area_PARK) END as bathy_score,---weighted coverage per unit area
		CASE WHEN hab_area_mapped is NULL THEN 0 ELSE sum(hab_area_mapped/area_PARK) END as hab_score, ---coverage per unit area
		CASE WHEN GA_score IS NULL THEN 0 ELSE (GA_score/area_PARK)*1000000 END as GA_score, ---observations per square kilometer
		CASE WHEN squidle_score IS NULL THEN 0 ELSE (squidle_score/area_PARK)*1000000 END as squidle_score, ---observations per square kilometer
		CASE WHEN MARS_score IS NULL THEN 0 ELSE (MARS_score/area_PARK)*1000000 END as MARS_score ---observations per square kilometer
		FROM (

---select region area for PARK
			(SELECT PARK, geometry::UnionAggregate(geom).STArea() as area_PARK
			FROM VW_BOUNDARY_AMP
			WHERE PARK <> 'HIMI'
			group by PARK) a

---STEP 1: get  habitat score-per-region (unweighted % only)
			LEFT JOIN
			(SELECT PARK, geometry::UnionAggregate(geom).STArea() as hab_area_mapped
			FROM BOUNDARY_AMP_HABITAT
			GROUP BY PARK) hab
			ON a.PARK = hab.PARK

---STEP 2: select bathy area mapped per resolution bin, and apply weighting (1 = <2m, 2 = 3-10m, 3 = 11-20m, 4, = 21-50m, 5 = >50m, 6 = unknown)
			LEFT JOIN
			(SELECT PARK, sum(res_weighting*area_mapped) AS bathy_weighted
			FROM	(SELECT PARK,
					CASE WHEN bathymetry_rank >= 6 THEN 0.5
					WHEN bathymetry_rank = 5 THEN 1
					WHEN bathymetry_rank = 4 THEN 3
					WHEN bathymetry_rank = 3 THEN 5
					WHEN bathymetry_rank = 2 THEN 7
					WHEN bathymetry_rank = 1 THEN 8
					END AS res_weighting,
					geometry::UnionAggregate(geom).STArea() as area_mapped
					FROM BOUNDARY_AMP_BATHYMETRY
					group by PARK, bathymetry_rank
					) sub
			GROUP BY PARK
			) bathy	
			ON a.PARK = bathy.PARK)

---STEP 3: select GlobalArchive and apply multiplicative weightings: <3 years old = 2, 3-5 years old = 1.5, otherwse 1. Multiplied by 1.5 if public/open.
			LEFT JOIN
			(SELECT PARK, sum(GA_weighting) AS GA_score
			FROM
			(SELECT PARK, date_weighting*openness_weighting AS GA_weighting
				FROM (
				SELECT PARK,
				CASE	WHEN datediff(month, deployment_date, getdate()) <= 36 THEN 2
						WHEN datediff(month, deployment_date, getdate()) BETWEEN 37 AND 60 THEN 1.5
							ELSE 1 END
						AS date_weighting,
				CASE	WHEN data_open = 'Y' THEN 1.5
						ELSE 1 END
						AS openness_weighting
				FROM BOUNDARY_AMP_HABITAT_OBS_GLOBALARCHIVE a
			INNER JOIN ---aggregates based on geometry (reduced overlapping points to single point)
			(
				SELECT id, deployment_date, data_open
				FROM TRANSFORM_GLOBALARCHIVE_DEPLOYMENT_POINTS_APPENDED
				WHERE
				substring(id, charindex('.', id)+1, len(id)-charindex('.', id)) ---deals with non-numeric ID column
				IN (
					SELECT MIN(substring(id, charindex('.', id)+1, len(id)-charindex('.', id))) ---selects minimum ID (we don't care which overlapping point we choose)
					FROM TRANSFORM_GLOBALARCHIVE_DEPLOYMENT_POINTS_APPENDED
					GROUP BY round(geom.STY/5,0)*5 ---round to nearest 5m
					)
				) b
			ON a.OBSERVATION=b.ID) sub1
			) sub2
			GROUP BY PARK) ga
			ON a.PARK = ga.PARK

---STEP 4: select Squidle and apply multiplicative weightings: <3 years old = 2, 3-5 years old = 1.5, otherwise 1. Multiplied by 1.5 if annotated (but private), multiplied by 2 if annotated and public
-----------CURRENTLY multiplied by image count
			LEFT JOIN
			(SELECT PARK, sum(squidle_weighting) AS squidle_score
			FROM (
				SELECT PARK, date_weighting*annotations_weighting*images AS squidle_weighting ---multiplying by weighting and image count
				FROM (
				SELECT PARK, images,
					CASE	WHEN datediff(month, DATE, getdate()) <= 36 THEN 2
					WHEN datediff(month, DATE, getdate()) BETWEEN 37 AND 60 THEN 1.5
					ELSE 1 END
					AS date_weighting,
					CASE	WHEN total_annotations > 0 AND public_annotations = 0 THEN 1.5
					WHEN total_annotations > 0 AND public_annotations > 0 THEN 2
					ELSE 1 END
					AS annotations_weighting
				FROM BOUNDARY_AMP_HABITAT_OBS_SQUIDLE a
				INNER JOIN ---aggregates based on geometry (reduced overlapping points to single point)
				(
				select * FROM VW_HABITAT_OBS_SQUIDLE
				WHERE DEPLOYMENT_ID
				IN (
					SELECT MIN(DEPLOYMENT_ID)
					FROM VW_HABITAT_OBS_SQUIDLE
					GROUP BY round(geom.STY/5,0)*5 ---round to nearest 5m
					)
				) b
				ON a.OBSERVATION=b.DEPLOYMENT_ID) sub1
				) sub2
			GROUP BY PARK) sq
			ON a.PARK = sq.PARK


---STEP 5: select MARS sediment and apply multiplicative weightings: <3 years old = 2, 3-5 years old = 1.5, otherwise 1. Multiplied by by 2 if analysed.
			LEFT JOIN
			(SELECT PARK, sum(MARS_weighting) AS MARS_score
			FROM (
			SELECT PARK, date_weighting*analysed_weighting AS MARS_weighting
				FROM (
					SELECT PARK,
					CASE	WHEN datediff(month, DATE, getdate()) <= 36 THEN 2
							WHEN datediff(month, DATE, getdate()) BETWEEN 37 AND 60 THEN 1.5
							ELSE 1 END
							AS date_weighting,
					CASE	WHEN b.ANALYSED = 'YES' THEN 2
							ELSE 2 END
							AS analysed_weighting
					FROM BOUNDARY_AMP_HABITAT_OBS_SEDIMENT a
					INNER JOIN ---aggregates based on geometry (reduced overlapping points to single point)
					(
					SELECT * FROM VW_HABITAT_OBS_SEDIMENT
					WHERE SAMPLE_ID
					IN (
						SELECT MIN(SAMPLE_ID)
						FROM VW_HABITAT_OBS_SEDIMENT
						GROUP BY round(geom.STY/5,0)*5 ---round to nearest 5m
						)
					) b
					ON a.OBSERVATION=b.sample_id) sub1
				) sub2
				GROUP BY PARK) m
				ON a.PARK = m.PARK

	GROUP BY a.PARK, a.area_PARK, bathy.bathy_weighted, hab.hab_area_mapped, ga.GA_score, sq.squidle_score, m.MARS_score

	) agg
)
GO
