PRINT N'Creating View [dbo].[VW_DATAPG_HABITAT_OBS]...';


GO


CREATE VIEW [dbo].[VW_DATAPG_HABITAT_OBS]
AS
(
SELECT a.Network, a.Park, '1_GlobalArchive' AS DType, b.data_open, b.geom
FROM
BOUNDARY_AMP_HABITAT_OBS_GLOBALARCHIVE a
LEFT JOIN VW_HABITAT_OBS_GLOBALARCHIVE b
ON a.observation=b.DEPLOYMENT_ID
UNION ALL
SELECT a.Network, a.Park, '2_Squidle' AS DType, (CASE WHEN b.public_annotations <> 0 THEN 'Y' ELSE 'N' END) AS data_open, b.geom
FROM
BOUNDARY_AMP_HABITAT_OBS_SQUIDLE a
LEFT JOIN VW_HABITAT_OBS_SQUIDLE b
ON a.observation=b.DEPLOYMENT_ID
UNION ALL
SELECT a.Network, a.Park, '3_Sediment' AS DType,
(CASE WHEN ANALYSED = 'YES' THEN 'Y' ELSE 'N' END) AS data_open,
b.geom
FROM
BOUNDARY_AMP_HABITAT_OBS_SEDIMENT a
LEFT JOIN VW_HABITAT_OBS_SEDIMENT b
ON a.observation=b.SAMPLE_ID
)
GO
