PRINT N'Creating Function [dbo].[path_intersections]...';


GO
-- Calculate all the intersections along a path, together with an attribute of interest from the intersected polygon.
-- Assumption is that the input is a LINESTRING, and the intersected geometries are all polygons.
-- Any overlaps are clipped, with earlier polygons have priority over (clipping) later ones in @habitat.

CREATE FUNCTION path_intersections(@transect geometry, @habitat HabitatTableType READONLY)
RETURNS @TransectSegments TABLE (
  layer_name VARCHAR(max),
  name varchar(max),
  segment geometry
)
AS
BEGIN
  DECLARE @buffered geometry = @transect.STBuffer(0.01),
          @emptyshape geometry = geometry::STGeomFromText('GEOMETRYCOLLECTION EMPTY', 3112);

  WITH
  -- first narrow to polygons we care about (those that intersect our line of interest):
  -- UPDATE: we will do this refinement before invoking this procedure.  If using
  -- stand-alone, it might be convenient to reinstate this CTE, and replace all following
  -- instances of '@habitat' with 'valid_polygons':
  --valid_polygons AS (
  --  SELECT id, name, geom
  --  FROM @habitat
  --  WHERE geom.STIntersects(@transect) = 1)
  --,
  total_extent AS (
    SELECT geometry::UnionAggregate(geom) AS agg FROM @habitat
  )
  ,
  -- Polygons may not cover the entire length of the line; the difference gives us the bits outside our habitat data:
  external_area AS (
    SELECT ISNULL(@buffered.STDifference(agg), @buffered) AS diff FROM total_extent
  )
  ,
  -- We have to handle overlaps (both in the datasets, and when using multiple datasets)
  overlappers (id, layer_name, name, geom) AS (
    SELECT vl.id, vl.layer_name, vl.name, vr.geom
	FROM @habitat vl
	LEFT JOIN @habitat vr ON vl.geom.STIntersects(vr.geom) = 1 AND vl.id > vr.id
  )
  ,
  aggregated_overlappers (id, geom) AS (
    SELECT id, COALESCE(geometry::UnionAggregate(geom), geometry::STGeomFromText('POLYGON EMPTY', 3112))
	FROM overlappers
	GROUP BY id
  )
  ,
  valid_flattened_polygons (id, layer_name, name, geom) AS (
    SELECT p.id, p.layer_name, p.name, p.geom.STDifference(agg.geom)
	FROM @habitat p JOIN aggregated_overlappers agg
	ON p.id = agg.id
  )
  ,
  -- Intermediate results are just all the intersections; we'll flatten them as the final step:
  intermediate_results AS (
    SELECT layer_name, name, geom.STIntersection(@transect) AS intersections
    FROM
      (SELECT layer_name, name, geom FROM valid_flattened_polygons
      UNION ALL
      SELECT null AS layer_name, null AS name, diff AS geom FROM external_area
      ) AS results
  )

  -- Finally, flatten into the results table:
  INSERT INTO @TransectSegments
    SELECT layer.name AS layer_name, ir.name, simplified.geom
    FROM intermediate_results AS ir
    CROSS APPLY simplify_geoms(ir.intersections) AS simplified
    LEFT JOIN catalogue_layer AS layer ON layer.layer_name = ir.layer_name;
  RETURN;
END;
GO
PRINT N'Creating Procedure [dbo].[CreateSpatialIndex]...';


GO



CREATE   PROCEDURE [dbo].[CreateSpatialIndex]
    @IndexName NVARCHAR(128),
    @TableName NVARCHAR(128),
    @GeometryColumn NVARCHAR(128)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SQL NVARCHAR(MAX);
    DECLARE @MinX FLOAT, @MinY FLOAT, @MaxX FLOAT, @MaxY FLOAT;

    -- Dynamic SQL to get extent
    DECLARE @ExtentSQL NVARCHAR(MAX) = '
    WITH ENVELOPE AS (
        SELECT [' + @GeometryColumn + '].STEnvelope() AS envelope
        FROM dbo.' + QUOTENAME(@TableName) + '
    ),
    CORNERS AS (
        SELECT envelope.STPointN(1) AS point FROM ENVELOPE
        UNION ALL
        SELECT envelope.STPointN(3) FROM ENVELOPE
    )
    SELECT
        @MinX_OUT = MIN(point.STX),
        @MinY_OUT = MIN(point.STY),
        @MaxX_OUT = MAX(point.STX),
        @MaxY_OUT = MAX(point.STY)
    FROM CORNERS;';

    -- Run to get bounds
    EXEC sp_executesql
        @ExtentSQL,
        N'@MinX_OUT FLOAT OUTPUT, @MinY_OUT FLOAT OUTPUT, @MaxX_OUT FLOAT OUTPUT, @MaxY_OUT FLOAT OUTPUT',
        @MinX_OUT = @MinX OUTPUT,
        @MinY_OUT = @MinY OUTPUT,
        @MaxX_OUT = @MaxX OUTPUT,
        @MaxY_OUT = @MaxY OUTPUT;

    -- Create spatial index
    SET @SQL = '
    CREATE SPATIAL INDEX ' + QUOTENAME(@IndexName) + '
    ON dbo.' + QUOTENAME(@TableName) + '(' + QUOTENAME(@GeometryColumn) + ')
    USING GEOMETRY_GRID 
    WITH (
        BOUNDING_BOX = (' + CAST(@MinX AS VARCHAR(32)) + ', ' + CAST(@MinY AS VARCHAR(32)) + ', ' + CAST(@MaxX AS VARCHAR(32)) + ', ' + CAST(@MaxY AS VARCHAR(32)) + '),
        GRIDS =(LEVEL_1 = MEDIUM, LEVEL_2 = MEDIUM, LEVEL_3 = MEDIUM, LEVEL_4 = MEDIUM),
        CELLS_PER_OBJECT = 16,
        PAD_INDEX = OFF,
        STATISTICS_NORECOMPUTE = OFF,
        SORT_IN_TEMPDB = OFF,
        DROP_EXISTING = OFF,
        ONLINE = OFF,
        ALLOW_ROW_LOCKS = ON,
        ALLOW_PAGE_LOCKS = ON
    );';

    EXEC (@SQL);
END;
GO
PRINT N'Creating Procedure [dbo].[EXTRACT_NBHL_column_definitions]...';


GO
CREATE PROCEDURE EXTRACT_NBHL_column_definitions
    @new_NBHL_table SYSNAME
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @ReferenceTable SYSNAME = 'FINALPRODUCT_SeamapAus_current';

    SELECT 
        'ALTER TABLE [' + @new_NBHL_table + '] ALTER COLUMN [' + refcol.name + '] ' +
        UPPER(typ.name) + 
        CASE 
            WHEN typ.name IN ('varchar', 'nvarchar', 'char', 'nchar') 
                THEN '(' + 
                    CASE 
                        WHEN refcol.max_length = -1 THEN 'MAX' 
                        ELSE CAST(refcol.max_length / CASE WHEN typ.name LIKE 'n%' THEN 2 ELSE 1 END AS VARCHAR) 
                    END + ')'
            WHEN typ.name IN ('decimal', 'numeric') 
                THEN '(' + CAST(refcol.precision AS VARCHAR) + ',' + CAST(refcol.scale AS VARCHAR) + ')'
            ELSE ''
        END +
        CASE WHEN refcol.is_nullable = 1 THEN ' NULL' ELSE ' NOT NULL' END AS AlterStatement
    FROM sys.columns refcol
    JOIN sys.types typ ON refcol.user_type_id = typ.user_type_id
    WHERE refcol.object_id = OBJECT_ID(@ReferenceTable)
	AND refcol.name NOT IN ('ID', 'geom')  --Explicitly exclude ID and geom columns
      AND EXISTS (
          SELECT 1 
          FROM sys.columns tgtcol
          WHERE tgtcol.object_id = OBJECT_ID(@new_NBHL_table)
            AND tgtcol.name = refcol.name
      )
    ORDER BY refcol.column_id;
END;
GO
PRINT N'Creating Procedure [dbo].[IMPORT_GLOBALARCHIVE_DEPLOYMENT_POINTS]...';


GO
-- =============================================
-- Author:		Khanh Nguyen
-- Create date: 12/09/2022
-- Description:	Procedure to transform data for Global Archive Deployment Points
-- =============================================
CREATE   PROCEDURE [dbo].[IMPORT_GLOBALARCHIVE_DEPLOYMENT_POINTS]
AS
BEGIN
    -- SET NOCOUNT ON added to prevent extra result sets from
    -- interfering with SELECT statements.
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRANSACTION
    BEGIN TRY
        DECLARE @DECREASE_THRESHOLD FLOAT = 0.05
        DECLARE @PREVIOUS_TRANSFORMED_COUNT INT
        DECLARE @CURRENT_EXTRACTED_COUNT INT

        SELECT @CURRENT_EXTRACTED_COUNT = COUNT(*) FROM EXTRACT_GLOBALARCHIVE_DEPLOYMENT_POINTS;
        SELECT @PREVIOUS_TRANSFORMED_COUNT = COUNT(*) FROM TRANSFORM_GLOBALARCHIVE_DEPLOYMENT_POINTS;
        IF @CURRENT_EXTRACTED_COUNT < @PREVIOUS_TRANSFORMED_COUNT * (1 - @DECREASE_THRESHOLD)
        BEGIN
            RAISERROR('EXTRACT_GLOBALARCHIVE_DEPLOYMENT_POINTS records count decreases more than 5%% compared to TRANSFORM_GLOBALARCHIVE_DEPLOYMENT_POINTS', 16, 1)
        END
        TRUNCATE TABLE TRANSFORM_GLOBALARCHIVE_DEPLOYMENT_POINTS

        -- Vars for cursor
        DECLARE @FID nvarchar(255)
        DECLARE @CAMPAIGN_ID nvarchar(255)
        DECLARE @DEPLOYMENT_ID nvarchar(255)
        DECLARE @DEPLOYMENT_TIME nvarchar(255)
        DECLARE @DESCRIPTION nvarchar(255)
        DECLARE @DEPTH nvarchar(255)
        DECLARE @SITE nvarchar(255)
        DECLARE @STATUS nvarchar(255)
        DECLARE @SUCCESSFUL_COUNT nvarchar(255)
        DECLARE @SUCCESSFUL_LENGTH nvarchar(255)
        DECLARE @COORDINATES nvarchar(255)
        DECLARE @OBSERVER nvarchar(255)
        DECLARE @LOCATION nvarchar(255)
        DECLARE @CAMPAIGN_NAME nvarchar(255)
        DECLARE @CAMPAIGN_LINK nvarchar(255)
        DECLARE @PROJECT_NAME nvarchar(255)
        DECLARE @METHOD_NAME nvarchar(255)
        DECLARE @COLOUR nvarchar(255)
        DECLARE @GEOM geometry


        -- Vars for lookup ID's
        DECLARE @destCAMPAIGN_ID int
        DECLARE @destDEPLOYMENT_TIME datetime
        DECLARE @destDEPTH float

        DECLARE cGLOBALARCHIVEDATA CURSOR FOR
            SELECT FID, CAMPAIGN_ID, DEPLOYMENT_ID, DEPLOYMENT_TIME, DESCRIPTION, [DEPTH], SITE, STATUS,
                   SUCCESSFUL_COUNT, SUCCESSFUL_LENGTH, COORDINATES, OBSERVER, LOCATION, CAMPAIGN_NAME, CAMPAIGN_LINK, PROJECT_NAME, METHOD_NAME, COLOUR, GEOM
            FROM EXTRACT_GLOBALARCHIVE_DEPLOYMENT_POINTS;

        OPEN cGLOBALARCHIVEDATA

        FETCH NEXT FROM cGLOBALARCHIVEDATA INTO @FID, @CAMPAIGN_ID, @DEPLOYMENT_ID, @DEPLOYMENT_TIME, @DESCRIPTION, @DEPTH, @SITE, @STATUS,
                   @SUCCESSFUL_COUNT, @SUCCESSFUL_LENGTH, @COORDINATES, @OBSERVER, @LOCATION, @CAMPAIGN_NAME, @CAMPAIGN_LINK, @PROJECT_NAME, @METHOD_NAME, @COLOUR, @GEOM
        WHILE @@FETCH_STATUS = 0
        BEGIN


            SET @destCAMPAIGN_ID = TRY_PARSE(@CAMPAIGN_ID as INT)
            SET @destDEPLOYMENT_TIME = TRY_PARSE(@DEPLOYMENT_TIME as DATETIME)
            SET @destDEPTH = TRY_PARSE(@DEPTH as FLOAT)
            IF @GEOM IS NOT NULL
                SET @GEOM.STSrid = 3112

        INSERT INTO TRANSFORM_GLOBALARCHIVE_DEPLOYMENT_POINTS
            (FID, CAMPAIGN_ID, DEPLOYMENT_ID, DEPLOYMENT_TIME, DESCRIPTION, [DEPTH], SITE, STATUS, SUCCESSFUL_COUNT,
            SUCCESSFUL_LENGTH, COORDINATES, OBSERVER, LOCATION, CAMPAIGN_NAME, CAMPAIGN_LINK, PROJECT_NAME,
            METHOD_NAME, COLOUR, GEOM)
            VALUES
            (@FID, @destCAMPAIGN_ID, @DEPLOYMENT_ID, @destDEPLOYMENT_TIME, @DESCRIPTION, @destDEPTH, @SITE, @STATUS, @SUCCESSFUL_COUNT,
            @SUCCESSFUL_LENGTH, @COORDINATES, @OBSERVER, @LOCATION, @CAMPAIGN_NAME, @CAMPAIGN_LINK, @PROJECT_NAME,
            @METHOD_NAME, @COLOUR, @GEOM)

            FETCH NEXT FROM cGLOBALARCHIVEDATA INTO @FID, @CAMPAIGN_ID, @DEPLOYMENT_ID, @DEPLOYMENT_TIME, @DESCRIPTION, @DEPTH, @SITE, @STATUS,
                @SUCCESSFUL_COUNT, @SUCCESSFUL_LENGTH, @COORDINATES, @OBSERVER, @LOCATION, @CAMPAIGN_NAME, @CAMPAIGN_LINK, @PROJECT_NAME,
                @METHOD_NAME, @COLOUR, @GEOM
        END

        CLOSE cGLOBALARCHIVEDATA
        DEALLOCATE cGLOBALARCHIVEDATA
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION
        SELECT
            -1 AS Status,
            ERROR_NUMBER() AS ErrorNumber,
            ERROR_SEVERITY() AS ErrorSeverity,
            ERROR_STATE() AS ErrorState,
            ERROR_PROCEDURE() AS ErrorProcedure,
            ERROR_MESSAGE() AS ErrorMessage,
            ERROR_LINE() AS ErrorLine;
        RETURN
    END CATCH

    COMMIT TRANSACTION
    SELECT 0 as Status

END
GO
