        DECLARE @SAND_PERCENT nvarchar(255)
        DECLARE @GRAVEL_PERCENT nvarchar(255)
        DECLARE @CARBONATE_PERCENT nvarchar(255)
        DECLARE @BIOGENIC_SILICA_PERCENT nvarchar(255)
        DECLARE @FOLK_CLASS nvarchar(255)
