CREATE PROCEDURE [dbo].[refresh_RegionReportStars] AS
BEGIN
    DECLARE @BatchSize INT = 100;  -- Define the batch size
    DECLARE @MinID INT;
    DECLARE @MaxID INT;
    DECLARE @CurrentMinID INT;
    DECLARE @CurrentMaxID INT;

    -- Get the minimum and maximum ID values
    SELECT @MinID = MIN(ID), @MaxID = MAX(ID) FROM catalogue_regionreport;

    SET @CurrentMinID = @MinID;

    WHILE @CurrentMinID <= @MaxID
    BEGIN
        SET @CurrentMaxID = @CurrentMinID + @BatchSize - 1;

        -- Update for NETWORK_WEIGHTED
        UPDATE cr
        SET
            cr.habitat_state = b.hab_score,
            cr.bathymetry_state = b.bathy_score,
            cr.habitat_observations_state = b.HabObs_combined_score,
            cr.state_summary = CASE
                WHEN b.hab_score > 2 THEN 'There are excellent habitat maps for this region.'
                WHEN b.hab_score > 1 AND b.hab_score <= 2 THEN
                    CASE
                        WHEN b.bathy_score >= 4 THEN 
                            CASE
                                WHEN b.HabObs_combined_score <= 2 THEN 'There is excellent coverage of bathymetry maps for this region, but habitat observations are lacking. Existing habitat maps could be expanded by investing in more observational (imagery) surveys.'
                                WHEN b.HabObs_combined_score > 2 THEN 'There is excellent coverage of bathymetry maps and habitat observations for this region. Consider investing in processing existing data to expand the existing habitat maps.'
                            END
                        WHEN b.bathy_score > 2 AND b.bathy_score < 4 THEN
                            CASE
                                WHEN b.HabObs_combined_score <= 2 THEN 'There is good moderate of bathymetry maps for this region, but habitat observations are lacking. Existing habitat maps could be expanded by investing in more observational (imagery) surveys.'
                                WHEN b.HabObs_combined_score > 2 THEN 'There is moderate coverage of bathymetry maps and a high number of habitat observations for this region. There is some opportunity for processing of existing data, but collection of more bathymetry data would improve the state of research knowledge for this region.'
                            END
                        WHEN b.bathy_score <= 2 THEN 
                            CASE
                                WHEN b.HabObs_combined_score <= 2 THEN 'Some habitat mapping exists for this region, but coverage of bathymetry maps and habitat observations are lacking. The state of research knowledge could be improved by investing in more field surveys.'
                                WHEN b.HabObs_combined_score > 2 THEN 'There are a high number of habitat observations for this region, but bathymetry data is lacking. Existing habitat maps could be expanded by investing in more bathymetry surveys.'
                            END
                    END
                WHEN b.hab_score <= 1 THEN
                    CASE
                        WHEN b.bathy_score >= 4 THEN
                            CASE
                                WHEN b.HabObs_combined_score <= 2 THEN 'There is excellent coverage of bathymetry maps for this region, but habitat observations are lacking and habitat maps are poor. The state of research knowledge could be improved by investing in more observational (imagery) surveys.'
                                WHEN b.HabObs_combined_score > 2 THEN 'There is excellent coverage of bathymetry maps and habitat observations for this region, but habitat maps are poor. The state of research knowledge could be improved by investing in more desktop processing of existing data.'
                            END
                        WHEN b.bathy_score > 2 AND b.bathy_score < 4 THEN
                            CASE
                                WHEN b.HabObs_combined_score <= 2 THEN 'There is moderate coverage of bathymetry maps for this region, but habitat observations are lacking and habitat maps are poor. The state of research knowledge could be improved by investing in more observational (imagery) surveys.'
                                WHEN b.HabObs_combined_score > 2 THEN 'There is moderate coverage of bathymetry maps and a high number habitat observations for this region, but habitat maps are poor. There is some opportunity for processing of existing data, but investment in more field surveys would improve the state of research knowledge for this region.'
                            END
                        WHEN b.bathy_score <= 2 THEN 
                            CASE
                                WHEN b.HabObs_combined_score <= 2 THEN 'There is poor coverage of bathymetry maps and habitat observations for this region. The state of research knowledge could be improved by investing in more field surveys.'
                                WHEN b.HabObs_combined_score > 2 THEN 'There are a high number of habitat observations for this region, but bathymetry data is lacking and habitat maps are poor. The state of research knowledge could be improved by investing in more bathymetry surveys.'
                            END
                    END
                ELSE 'nil'
            END
        FROM
            catalogue_regionreport cr
        INNER JOIN AMP_state_of_knowledge_NETWORK_WEIGHTED b
        ON cr.Network = b.Network
        WHERE cr.ID BETWEEN @CurrentMinID AND @CurrentMaxID;

        -- Update for PARK_WEIGHTED
        UPDATE cr
        SET
            cr.habitat_state = b.hab_score,
            cr.bathymetry_state = b.bathy_score,
            cr.habitat_observations_state = b.HabObs_combined_score,
            cr.state_summary = CASE
                WHEN b.hab_score > 2 THEN 'There are excellent habitat maps for this region.'
                WHEN b.hab_score > 1 AND b.hab_score <= 2 THEN
                    CASE
                        WHEN b.bathy_score >= 4 THEN 
                            CASE
                                WHEN b.HabObs_combined_score <= 2 THEN 'There is excellent coverage of bathymetry maps for this region, but habitat observations are lacking. Existing habitat maps could be expanded by investing in more observational (imagery) surveys.'
                                WHEN b.HabObs_combined_score > 2 THEN 'There is excellent coverage of bathymetry maps and habitat observations for this region. Consider investing in processing existing data to expand the existing habitat maps.'
                            END
                        WHEN b.bathy_score > 2 AND b.bathy_score < 4 THEN
                            CASE
                                WHEN b.HabObs_combined_score <= 2 THEN 'There is good moderate of bathymetry maps for this region, but habitat observations are lacking. Existing habitat maps could be expanded by investing in more observational (imagery) surveys.'
                                WHEN b.HabObs_combined_score > 2 THEN 'There is moderate coverage of bathymetry maps and a high number of habitat observations for this region. There is some opportunity for processing of existing data, but collection of more bathymetry data would improve the state of research knowledge for this region.'
                            END
                        WHEN b.bathy_score <= 2 THEN 
                            CASE
                                WHEN b.HabObs_combined_score <= 2 THEN 'Some habitat mapping exists for this region, but coverage of bathymetry maps and habitat observations are lacking. The state of research knowledge could be improved by investing in more field surveys.'
                                WHEN b.HabObs_combined_score > 2 THEN 'There are a high number of habitat observations for this region, but bathymetry data is lacking. Existing habitat maps could be expanded by investing in more bathymetry surveys.'
                            END
                    END
                WHEN b.hab_score <= 1 THEN
                    CASE
                        WHEN b.bathy_score >= 4 THEN
                            CASE
                                WHEN b.HabObs_combined_score <= 2 THEN 'There is excellent coverage of bathymetry maps for this region, but habitat observations are lacking and habitat maps are poor. The state of research knowledge could be improved by investing in more observational (imagery) surveys.'
                                WHEN b.HabObs_combined_score > 2 THEN 'There is excellent coverage of bathymetry maps and habitat observations for this region, but habitat maps are poor. The state of research knowledge could be improved by investing in more desktop processing of existing data.'
                            END
                        WHEN b.bathy_score > 2 AND b.bathy_score < 4 THEN
                            CASE
                                WHEN b.HabObs_combined_score <= 2 THEN 'There is moderate coverage of bathymetry maps for this region, but habitat observations are lacking and habitat maps are poor. The state of research knowledge could be improved by investing in more observational (imagery) surveys.'
                                WHEN b.HabObs_combined_score > 2 THEN 'There is moderate coverage of bathymetry maps and a high number habitat observations for this region, but habitat maps are poor. There is some opportunity for processing of existing data, but investment in more field surveys would improve the state of research knowledge for this region.'
                            END
                        WHEN b.bathy_score <= 2 THEN 
                            CASE
                                WHEN b.HabObs_combined_score <= 2 THEN 'There is poor coverage of bathymetry maps and habitat observations for this region. The state of research knowledge could be improved by investing in more field surveys.'
                                WHEN b.HabObs_combined_score > 2 THEN 'There are a high number of habitat observations for this region, but bathymetry data is lacking and habitat maps are poor. The state of research knowledge could be improved by investing in more bathymetry surveys.'
                            END
                    END
                ELSE 'nil'
            END
        FROM
            catalogue_regionreport cr
        INNER JOIN AMP_state_of_knowledge_PARK_WEIGHTED b
        ON cr.Park = b.Park
        WHERE cr.ID BETWEEN @CurrentMinID AND @CurrentMaxID;

        -- Move to the next batch
        SET @CurrentMinID = @CurrentMaxID + 1;
    END;
END;
GO
PRINT N'Creating Procedure [dbo].[SeamapAus_Add_Boundary]...';


GO
-- =============================================
-- Author:		Mark Hepburn, Condense
-- Create date: 12/12/2017
-- Description:	Update the region-statistics precomputation table when a new boundary layer is added.  Assumes that the view SeamapAus_Boundaries_View has already been updated.
-- =============================================
CREATE PROCEDURE SeamapAus_Add_Boundary
	@boundary_layer_id int
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	-- Depending on how confident we felt, we could also make this
	-- idempotent by deleting everything with that habitat-layer id
	-- first... instead we will warn if it's already present.
    IF EXISTS(SELECT * FROM SeamapAus_Habitat_By_Region WHERE boundary_layer_id = @boundary_layer_id)
        THROW 65200, 'Data already exists for that boundary layer', 0;

    INSERT INTO SeamapAus_Habitat_By_Region (boundary_layer_id, habitat_layer_id, habitat, region, boundary_area, area, geom)
    SELECT boundary_layer_id, habitat_layer_id, habitat, region, boundary_area, sum(region_area) AS area, geometry::UnionAggregate(region_geom) AS geom--, sum(percentage) as percentage
    FROM (
      SELECT boundary_layer_id, habitat_layer_id, region, boundary_area, habitat, region_geom, region_geom.STArea() AS region_area--, 100 * region_geom.STArea() / boundary_area as percentage
      FROM (
        SELECT bc.id AS boundary_layer_id, hc.id AS habitat_layer_id, h.habitat, b.region, b.geom.STIntersection(h.geom) AS region_geom, b.geom.STArea() AS boundary_area
        FROM SeamapAus_Boundaries_View b
        JOIN SeamapAus_Regions_VIEW h on b.geom.STIntersects(h.geom) = 1
        JOIN catalogue_layer bc ON b.boundary_layer = COALESCE(bc.detail_layer, bc.layer_name)
        JOIN catalogue_layer hc ON h.layer_name     = COALESCE(hc.detail_layer, hc.layer_name)
        WHERE bc.id = @boundary_layer_id
      ) sub1
    ) sub2
    GROUP BY boundary_layer_id, habitat_layer_id, habitat, region, boundary_area;

END
GO
