CREATE PROCEDURE [dbo].[UpdateBathymetry_singleAMP]
  @parks NVARCHAR(MAX)
AS
BEGIN
  DECLARE @resolution VARCHAR(10);

 DECLARE resolution_cursor CURSOR FOR 
  SELECT DISTINCT RESOLUTION FROM VW_BATHYMETRY
  ORDER BY RESOLUTION asc;

  OPEN resolution_cursor;

  FETCH NEXT FROM resolution_cursor INTO @resolution;

  WHILE @@FETCH_STATUS = 0
  BEGIN

    -- Begin bathymetry geometry aggregation
    DELETE FROM [dbo].[GeometryAggregationTable_PARTIAL];
    
    INSERT INTO [dbo].[GeometryAggregationTable_PARTIAL]
    SELECT
      b.[geom]
    FROM [dbo].[VW_BATHYMETRY] b
    INNER JOIN [dbo].[VW_BOUNDARY_AMP] a ON b.geom.STIntersects(a.geom) = 1
    WHERE b.[RESOLUTION] = @resolution AND a.Park IN (SELECT value FROM dbo.SplitString(@parks, ','));
    
    DECLARE @geom GEOMETRY = (
      SELECT GEOMETRY::UnionAggregate([geom])
      FROM [dbo].[GeometryAggregationTable_PARTIAL]
    );

    DECLARE @rank INT = (
      SELECT [RANK]
      FROM (
        SELECT TOP(1) *
        FROM [dbo].[VW_BATHYMETRY]
        WHERE [RESOLUTION] = @resolution
      ) AS [T1]
    );

	-- Update BathymetryGeoms_PARTIAL  (your original DELETE remains)
	BEGIN TRANSACTION;
	  DELETE FROM [dbo].[BathymetryGeoms_PARTIAL] WHERE [RESOLUTION] = @resolution;

	  -- >>> minimal change: only insert if @geom exists and is not empty
	  IF (@geom IS NOT NULL AND @geom.STIsEmpty() = 0)
	  BEGIN
		INSERT INTO [dbo].[BathymetryGeoms_PARTIAL] ([RESOLUTION], [RANK], [geom])
		VALUES (@resolution, @rank, @geom);
	  END
	  -- <<< end minimal change

	COMMIT;

  -- Update UniqueBathymetryGeoms_partial
  BEGIN TRANSACTION;
    DELETE FROM [dbo].[UniqueBathymetryGeoms_partial] WHERE [RANK] >= @rank;
    INSERT INTO [dbo].[UniqueBathymetryGeoms_partial] ([RESOLUTION], [RANK], [geom])
    SELECT
      [RESOLUTION],
      [RANK],
      COALESCE([geom].STDifference((
        SELECT geometry::UnionAggregate([b2].[geom])
        FROM [dbo].[BathymetryGeoms_PARTIAL] AS [b2]
        WHERE [b2].[RANK] < [b1].[RANK]
      )), [geom]) AS [geom]
    FROM [dbo].[BathymetryGeoms_PARTIAL] AS [b1]
    WHERE [RANK] >= @rank;
  COMMIT;

  -- Update BOUNDARY_AMP_BATHYMETRY
  BEGIN TRANSACTION;
    DELETE FROM [dbo].[BOUNDARY_AMP_BATHYMETRY_PARTIAL] WHERE [bathymetry_rank] >= @rank;
    INSERT INTO [dbo].[BOUNDARY_AMP_BATHYMETRY_PARTIAL] ([Network], [Park], [Zone_Category], [IUCN_Category], [Zone_ID], [bathymetry_resolution], [bathymetry_rank], [geom], [area])
    SELECT
      [boundary].[Network],
      [boundary].[Park],
      [boundary].[Zone_Category],
      [boundary].[IUCN_Category],
      [boundary].[Zone_ID],
      [bathymetry].[RESOLUTION] AS [bathymetry_resolution],
      [bathymetry].[RANK] AS [bathymetry_rank],
      [bathymetry].[geom],
      [bathymetry].[geom].STArea() AS [area]
    FROM [dbo].[VW_BOUNDARY_AMP] AS [boundary]
    CROSS APPLY [dbo].unique_bathymetry_intersections_PARTIAL([boundary].[geom]) AS [bathymetry]
    WHERE [bathymetry].[RANK] >= @rank AND [boundary].[Park] IN (SELECT value FROM dbo.SplitString(@parks, ','));
  COMMIT;

    FETCH NEXT FROM resolution_cursor INTO @resolution;
  END;

  CLOSE resolution_cursor;
  DEALLOCATE resolution_cursor;
END;
GO
